import random
import struct
from typing import Tuple

# This generator produces raw pixel data buffers suitable for LodePNG encoding/conversion
# fuzzers that request unstructured raw pixels. It focuses on generating small images
# (to match the stubs' bounds) with patterns that exercise different encoder paths:
# - solid colors, gradients, checkerboards
# - alpha on/off, greyscale vs RGB(A)
# - 8-bit and 16-bit big-endian samples
# - palette-friendly limited-color images (even when not explicitly palette type)
# The fuzzing harness sets width/height/colortype/bitdepth independently; our buffer
# should be interesting under many combinations while still valid raw data sequences.

MAX_BYTES = 2048

# Enumerate logical formats we may target to keep data layout coherent with common choices
# The harness most often uses non-paletted formats; we support GREY, RGB, GA, RGBA
FORMATS = [
    ("GREY", 1),
    ("RGB", 3),
    ("GA", 2),
    ("RGBA", 4),
]

# Choose dimensions that keep total bytes <= 2048 even for 16-bit and 4 channels
# For worst case (RGBA, 16-bit => 8 bytes/pixel), 16x16 = 2048 bytes.
DIM_CANDIDATES = [
    (1, 1), (2, 2), (3, 3), (4, 4),
    (8, 8), (16, 16), (32, 4), (4, 32), (8, 16), (16, 8), (7, 13), (13, 7)
]


def _pick_dims(rng: random.Random, bpp_bytes: int) -> Tuple[int, int]:
    # Filter candidates that fit under MAX_BYTES for chosen bytes-per-pixel
    choices = []
    for w, h in DIM_CANDIDATES:
        if w * h * bpp_bytes <= MAX_BYTES:
            choices.append((w, h))
    if not choices:
        return 1, 1
    return rng.choice(choices)


def _pattern_solid(w: int, h: int, chans: int, bitdepth: int, rng: random.Random) -> bytes:
    # Few canonical solids to encourage palette/alpha handling
    solids8 = [
        [0, 0, 0, 255],      # black / opaque
        [255, 255, 255, 255],# white / opaque
        [255, 0, 0, 255],    # red
        [0, 255, 0, 255],    # green
        [0, 0, 255, 255],    # blue
        [0, 0, 0, 0],        # fully transparent
        [128, 128, 128, 255] # mid grey
    ]
    c = rng.choice(solids8)
    if chans == 1:
        pix8 = [c[0]]
    elif chans == 2:
        pix8 = [c[0], c[3]]
    elif chans == 3:
        pix8 = c[:3]
    else:
        pix8 = c[:4]
    if bitdepth == 8:
        pix = bytes(pix8)
    else:
        # 16-bit big-endian: duplicate each 8-bit value to high/low for simplicity
        pix = b"".join(struct.pack(">H", v * 257) for v in pix8)
    return pix * (w * h)


def _pattern_checker(w: int, h: int, chans: int, bitdepth: int, rng: random.Random) -> bytes:
    # 2x2 checker repeated: colors chosen from small palette
    colors = [
        (0, 0, 0, 255), (255, 255, 255, 255), (255, 0, 255, 255), (0, 255, 255, 255),
        (255, 255, 0, 255), (0, 0, 0, 0)
    ]
    a = rng.choice(colors)
    b = rng.choice(colors)
    if chans == 1:
        ca = [a[0]]; cb = [b[0]]
    elif chans == 2:
        ca = [a[0], a[3]]; cb = [b[0], b[3]]
    elif chans == 3:
        ca = list(a[:3]); cb = list(b[:3])
    else:
        ca = list(a[:4]); cb = list(b[:4])

    def pack(pix8):
        if bitdepth == 8:
            return bytes(pix8)
        return b"".join(struct.pack(">H", v * 257) for v in pix8)

    pa = pack(ca); pb = pack(cb)
    row = []
    for y in range(h):
        line = []
        for x in range(w):
            line.append(pa if ((x ^ y) & 1) == 0 else pb)
        row.append(b"".join(line))
    return b"".join(row)


def _pattern_gradient(w: int, h: int, chans: int, bitdepth: int) -> bytes:
    # Horizontal/vertical gradient combining channels; for GA, alpha ramps; for GREY, luminance
    buf = bytearray()
    for y in range(h):
        for x in range(w):
            fx = x / max(1, w - 1)
            fy = y / max(1, h - 1)
            r = int(255 * fx)
            g = int(255 * fy)
            b = int(255 * ((fx + fy) * 0.5))
            a = int(255 * (1.0 - fx))
            if chans == 1:
                pix8 = [b]  # use mixed value
            elif chans == 2:
                pix8 = [b, a]
            elif chans == 3:
                pix8 = [r, g, b]
            else:
                pix8 = [r, g, b, a]
            if bitdepth == 8:
                buf.extend(pix8)
            else:
                for v in pix8:
                    buf.extend(struct.pack(">H", v * 257))
    return bytes(buf)


def _pattern_palette_friendly(w: int, h: int, chans: int, bitdepth: int, rng: random.Random) -> bytes:
    # Use up to 4 colors in blocks to be palette-friendly
    base = [
        (0,0,0,255),(255,255,255,255),(255,0,0,255),(0,255,0,255),
        (0,0,255,255),(255,255,0,255),(0,255,255,255),(255,0,255,255)
    ]
    cols = rng.sample(base, k=4)
    block = max(1, min(w, h) // 4)

    def sel(ix):
        c = cols[ix % len(cols)]
        if chans == 1:
            return [c[0]]
        if chans == 2:
            return [c[0], c[3]]
        if chans == 3:
            return [c[0], c[1], c[2]]
        return [c[0], c[1], c[2], c[3]]

    def pack(pix8):
        if bitdepth == 8:
            return bytes(pix8)
        return b"".join(struct.pack(">H", v * 257) for v in pix8)

    rows = []
    for y in range(h):
        line = []
        for x in range(w):
            ix = (x // block) + (y // block)
            line.append(pack(sel(ix)))
        rows.append(b"".join(line))
    return b"".join(rows)


def _random_noise(w: int, h: int, chans: int, bitdepth: int, rng: random.Random) -> bytes:
    # Fully random pixels within valid range; useful to hit entropy-heavy paths
    count = w * h * chans
    if bitdepth == 8:
        return bytes(rng.getrandbits(8) for _ in range(count))
    # 16-bit big-endian: choose biased values including 0, 255, 65535 and midpoints
    choices = [0, 1, 255, 256, 511, 32768, 65535]
    out = bytearray()
    for _ in range(count):
        if rng.random() < 0.6:
            v = rng.choice(choices)
        else:
            v = rng.getrandbits(16)
        out.extend(struct.pack(">H", v))
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Pick format and bit depth
    fmt_name, chans = rng.choice(FORMATS)
    bitdepth = 16 if rng.random() < 0.4 else 8  # prefer 8-bit, sometimes 16-bit
    bytes_per_sample = 2 if bitdepth == 16 else 1
    bpp_bytes = chans * bytes_per_sample

    # Pick dimensions fitting the fuzzers' constraints
    w, h = _pick_dims(rng, bpp_bytes)

    # Pick a content pattern
    patterns = [
        _pattern_solid,
        _pattern_checker,
        _pattern_gradient,
        _pattern_palette_friendly,
        _random_noise,
    ]
    pattern_fn = rng.choice(patterns)

    data = pattern_fn(w, h, chans, bitdepth, rng) if pattern_fn in (
        _pattern_solid, _pattern_checker, _pattern_palette_friendly, _random_noise
    ) else _pattern_gradient(w, h, chans, bitdepth)

    # Ensure size is exactly w*h*bpp
    expected = w * h * bpp_bytes
    if len(data) != expected:
        data = data[:expected].ljust(expected, b"\x00")

    # Return bytes buffer; harness will resize/match as needed. Keep under 2048 bytes.
    if len(data) > MAX_BYTES:
        data = data[:MAX_BYTES]
    return data

import random
import struct
from typing import List, Tuple

# Generator for raw 24-bit RGB image buffers (no headers), tightly packed R,G,B per pixel.
# Target fuzzers:
# - lodepng_encode24: consumes FUZZ_PARAM_STR resized to w*h*3
# - lodepng_encode24_file: same image buffer, filename irrelevant to this generator
# Constraints from stub: w,h in [1,64], and image_size <= 2048 bytes
# Therefore max pixels = floor(2048/3) = 682 pixels. We will pick diverse WxH that satisfy this.

# We produce patterns that are valid RGB data and try to exercise different encoder paths
# (solid colors, gradients, checkerboards, stripes, palettes, random noise, alpha-like edges in RGB,
# varied widths/heights, prime dimensions, powers of two, etc.).

_MAX_SIZE = 2048

# Preselected interesting (w,h) pairs within the constraint w*h*3 <= 2048
_INTERESTING_DIMS: List[Tuple[int, int]] = [
    (1, 1), (2, 2), (3, 3), (4, 4),
    (7, 7), (8, 8), (9, 9), (11, 11), (13, 13),
    (16, 8), (8, 16), (17, 17), (19, 11), (11, 19),
    (31, 7), (7, 31), (29, 5), (5, 29),
    (32, 16), (16, 32), # too big? check later against limit
    (37, 7), (7, 37), (41, 5), (5, 41),
    (53, 5), (5, 53), (61, 3), (3, 61),
]

# Filter out any exceeding 2048 bytes or >64
_INTERESTING_DIMS = [
    (w, h) for (w, h) in _INTERESTING_DIMS
    if 1 <= w <= 64 and 1 <= h <= 64 and (w * h * 3) <= _MAX_SIZE
]

# Additional procedural selection will consider full range but clamp to limit.

def _choose_dims(rng: random.Random) -> Tuple[int, int]:
    # 60% pick from curated set, 40% random but constrained
    if _INTERESTING_DIMS and rng.random() < 0.6:
        return rng.choice(_INTERESTING_DIMS)
    # Random selection within bounds
    for _ in range(10):
        w = rng.randint(1, 64)
        h = rng.randint(1, 64)
        if w * h * 3 <= _MAX_SIZE:
            return (w, h)
    # Fallback to a safe small size
    return (16, 16) if (16 * 16 * 3) <= _MAX_SIZE else (8, 8)

# Pattern generators return bytes of length w*h*3

def _solid_color(w: int, h: int, r: int, g: int, b: int) -> bytes:
    return bytes([r, g, b]) * (w * h)

def _horizontal_gradient(w: int, h: int) -> bytes:
    buf = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            t = x / (w - 1) if w > 1 else 0.0
            r = int(255 * t)
            g = int(255 * (1.0 - t))
            b = int(255 * (0.5 + 0.5 * (1.0 - t))) if w > 1 else 0
            i = (y * w + x) * 3
            buf[i:i+3] = bytes((r & 0xFF, g & 0xFF, b & 0xFF))
    return bytes(buf)


def _vertical_gradient(w: int, h: int) -> bytes:
    buf = bytearray(w * h * 3)
    for y in range(h):
        t = y / (h - 1) if h > 1 else 0.0
        for x in range(w):
            r = int(255 * (1.0 - t))
            g = int(255 * t)
            b = int(255 * (t * (1.0 - t) * 4))
            i = (y * w + x) * 3
            buf[i:i+3] = bytes((r & 0xFF, g & 0xFF, b & 0xFF))
    return bytes(buf)


def _checkerboard(w: int, h: int, size: int = 4, c0=(0, 0, 0), c1=(255, 255, 255)) -> bytes:
    buf = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            cx = (x // max(1, size)) & 1
            cy = (y // max(1, size)) & 1
            c = c0 if (cx ^ cy) == 0 else c1
            i = (y * w + x) * 3
            buf[i:i+3] = bytes(c)
    return bytes(buf)


def _stripes(w: int, h: int, vertical: bool = True, period: int = 3) -> bytes:
    buf = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            s = (x if vertical else y) // max(1, period)
            if s % 3 == 0:
                c = (255, 0, 0)
            elif s % 3 == 1:
                c = (0, 255, 0)
            else:
                c = (0, 0, 255)
            i = (y * w + x) * 3
            buf[i:i+3] = bytes(c)
    return bytes(buf)


def _palette_cycle(w: int, h: int, palette: List[Tuple[int, int, int]]) -> bytes:
    buf = bytearray(w * h * 3)
    p = palette
    plen = max(1, len(p))
    for y in range(h):
        for x in range(w):
            c = p[(y * w + x) % plen]
            i = (y * w + x) * 3
            buf[i:i+3] = bytes(c)
    return bytes(buf)


def _noise(w: int, h: int, rng: random.Random) -> bytes:
    return bytes(rng.getrandbits(8) for _ in range(w * h * 3))


def _edges(w: int, h: int) -> bytes:
    # Emphasize extreme values and transitions to exercise filtering
    buf = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            t = 255 if (x == 0 or y == 0 or x == w - 1 or y == h - 1) else 0
            i = (y * w + x) * 3
            buf[i:i+3] = bytes((t, 255 - t, (x * 17 + y * 31) & 0xFF))
    return bytes(buf)


def _radial(w: int, h: int) -> bytes:
    cx = (w - 1) / 2.0
    cy = (h - 1) / 2.0
    maxd2 = max(1.0, cx * cx + cy * cy)
    buf = bytearray(w * h * 3)
    for y in range(h):
        for x in range(w):
            dx = x - cx
            dy = y - cy
            d = (dx * dx + dy * dy) / maxd2
            r = int(255 * (1.0 - d))
            g = int(255 * (d))
            b = int(255 * (0.5 + 0.5 * (1.0 - d)))
            i = (y * w + x) * 3
            buf[i:i+3] = bytes((max(0, min(255, r)), max(0, min(255, g)), max(0, min(255, b))))
    return bytes(buf)


def _make_image(w: int, h: int, rng: random.Random) -> bytes:
    # Select a pattern family
    choice = rng.random()
    if choice < 0.12:
        # Solid color variants
        solids = [
            (0, 0, 0), (255, 255, 255), (255, 0, 0), (0, 255, 0), (0, 0, 255),
            (255, 255, 0), (0, 255, 255), (255, 0, 255), (17, 34, 51)
        ]
        r, g, b = rng.choice(solids)
        return _solid_color(w, h, r, g, b)
    elif choice < 0.24:
        return _horizontal_gradient(w, h)
    elif choice < 0.36:
        return _vertical_gradient(w, h)
    elif choice < 0.48:
        size = rng.choice([1, 2, 3, 4, 5, 7, 8])
        c0 = rng.choice([(0, 0, 0), (16, 16, 16), (255, 0, 255), (0, 0, 0)])
        c1 = rng.choice([(255, 255, 255), (240, 240, 240), (0, 255, 0), (255, 255, 255)])
        return _checkerboard(w, h, size=size, c0=c0, c1=c1)
    elif choice < 0.60:
        vertical = rng.choice([True, False])
        period = rng.choice([1, 2, 3, 4, 5, 7, 8])
        return _stripes(w, h, vertical=vertical, period=period)
    elif choice < 0.72:
        palette = [
            (0, 0, 0), (255, 255, 255), (255, 0, 0), (0, 255, 0), (0, 0, 255),
            (255, 255, 0), (0, 255, 255), (255, 0, 255), (128, 128, 128),
            (16, 32, 48), (64, 128, 192)
        ]
        rng.shuffle(palette)
        return _palette_cycle(w, h, palette[:rng.randint(2, min(11, max(2, w*h)))])
    elif choice < 0.84:
        return _noise(w, h, rng)
    elif choice < 0.92:
        return _edges(w, h)
    else:
        return _radial(w, h)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Choose dimensions ensuring the size limit
    w, h = _choose_dims(rng)
    size = w * h * 3
    if size > _MAX_SIZE:
        # As a safety net, shrink h
        h = max(1, _MAX_SIZE // (w * 3))
        size = w * h * 3

    img = _make_image(w, h, rng)

    # Ensure exact size matching w*h*3
    if len(img) != size:
        # Resize or truncate deterministically
        if len(img) < size:
            img = img + bytes(size - len(img))
        else:
            img = img[:size]

    return img

import random
import struct
import zlib
from typing import Tuple

# This generator produces a standalone PNG-like chunk buffer:
# [length:4][type:4][data:length][crc:4]
# It aims to be valid and interesting for lodepng_* chunk utilities and lodepng_inspect_chunk.
# The payload is crafted based on the chosen chunk type to satisfy basic structural expectations
# (e.g., tEXt keyword format, pHYs 9-byte payload, gAMA 4-byte gamma, iCCP structure, bKGD sizes,
# tRNS minimal structures), but remains small (<=4096 bytes total).

ASCII_TYPES = [b"tEXt", b"pHYs", b"gAMA", b"iCCP", b"bKGD", b"tRNS", b"IDAT", b"IHDR"]

# Helpers for specific chunk payloads

def _u32be(v: int) -> bytes:
    return struct.pack('>I', v & 0xFFFFFFFF)

def _clamp(v: int, lo: int, hi: int) -> int:
    return max(lo, min(hi, v))

def _rand_keyword(rng: random.Random) -> bytes:
    # PNG tEXt/iCCP keyword: 1..79 bytes, Latin-1, no nulls
    length = rng.randint(1, 20)
    # Simple readable ASCII
    chars = [rng.choice(b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_ ") for _ in range(length)]
    # Avoid leading/trailing spaces per common practice (not strictly required)
    if chars[0] == 0x20:
        chars[0] = ord('K')
    if chars[-1] == 0x20:
        chars[-1] = ord('W')
    return bytes(chars)

def _payload_tEXt(rng: random.Random, max_len: int) -> bytes:
    # Structure: keyword (1..79) + 0 + text (Latin-1, may be empty)
    key = _rand_keyword(rng)
    # Ensure total length <= max_len when possible; otherwise trim text
    remaining = max_len - (len(key) + 1)
    remaining = max(0, remaining)
    # Produce a short, readable text to encourage parsing paths
    base_texts = [
        b"hello", b"width=800;height=600", b"Author: LodePNG", b"Comment",
        b"pHYs test", b"gamma info", b"crc check"
    ]
    text = rng.choice(base_texts)
    if len(text) > remaining:
        text = text[:remaining]
    return key + b"\x00" + text

def _payload_pHYs(rng: random.Random) -> bytes:
    # 9 bytes: 4 bytes X pixels per unit, 4 bytes Y pixels per unit, 1 byte unit specifier (0 or 1)
    xppu = rng.randint(1, 20000)
    yppu = rng.randint(1, 20000)
    unit = rng.choice([0, 1])
    return _u32be(xppu) + _u32be(yppu) + bytes([unit])

def _payload_gAMA(rng: random.Random) -> bytes:
    # 4 bytes: gamma = int(gamma*100000). Common values: 45455 (gamma 0.45455), 100000 (1.0)
    val = rng.choice([45455, 100000, rng.randint(1000, 200000)])
    return _u32be(val)

def _payload_iCCP(rng: random.Random, max_len: int) -> bytes:
    # iCCP: profile_name (1..79, no null) + 0 + compression_method(0) + compressed_profile
    # We'll generate a small valid zlib stream of arbitrary bytes to stay valid.
    name = _rand_keyword(rng)
    comp_method = b"\x00"  # deflate
    # Create a small ICC payload body and zlib-compress it
    icc_body_base = b"ICC_PROFILE\x00\x01sRGB\x02\x10" + bytes(rng.getrandbits(8) for _ in range(rng.randint(8, 32)))
    comp = zlib.compress(icc_body_base)
    # Fit within max_len if needed
    head = name + b"\x00" + comp_method
    remaining = max_len - len(head)
    if remaining < 0:
        # If max_len is too small, fallback to minimal viable structure with empty compressed payload
        # Note: empty deflate stream is b'x\x9c\x03\x00\x00\x00\x00\x01'
        comp = zlib.compress(b"")
        head = name[:max(1, max_len-1)] + b"\x00"  # comp_method may not fit; ensure at least keyword+NUL
        if len(head) < max_len:
            head += b"\x00"
        return head[:max_len]
    if len(comp) > remaining:
        # Trim by recompressing smaller payload
        target = _clamp(remaining, 8, 64)
        icc_body = bytes(rng.getrandbits(8) for _ in range(target // 2))
        comp = zlib.compress(icc_body)
        comp = comp[:remaining]
    return head + comp

def _payload_bKGD(rng: random.Random, colortype: int = None) -> bytes:
    # Size depends on color type in IHDR, but lodepng_inspect_chunk may validate only basic shape.
    # Provide common variants: grayscale(2), truecolor(6), indexed(1)
    variant = rng.choice(['grey', 'rgb', 'palette'])
    if variant == 'grey':
        # 2 bytes (big-endian)
        return struct.pack('>H', rng.randint(0, 65535))
    elif variant == 'rgb':
        # 6 bytes: 2 bytes each R,G,B
        return struct.pack('>HHH', rng.randint(0, 65535), rng.randint(0, 65535), rng.randint(0, 65535))
    else:
        # palette index: 1 byte
        return bytes([rng.randint(0, 255)])

def _payload_tRNS(rng: random.Random) -> bytes:
    # Variants: grayscale(2), truecolor(6), palette(n bytes). We'll produce small palette variant or RGB.
    variant = rng.choice(['grey', 'rgb', 'palette'])
    if variant == 'grey':
        return struct.pack('>H', rng.randint(0, 65535))
    elif variant == 'rgb':
        return struct.pack('>HHH', rng.randint(0, 65535), rng.randint(0, 65535), rng.randint(0, 65535))
    else:
        # 1..8 bytes of alpha for palette entries
        n = rng.randint(1, 8)
        return bytes(rng.getrandbits(8) for _ in range(n))

def _payload_IDAT(rng: random.Random, max_len: int) -> bytes:
    # Small DEFLATE compressed payload of arbitrary bytes; lodepng won't decode here but CRC utilities accept any
    raw = bytes(rng.getrandbits(8) for _ in range(rng.randint(0, max(0, min(64, max_len)))))
    # For variety, sometimes return uncompressed-like data for testing (still arbitrary for chunk utils)
    if rng.random() < 0.5 and raw:
        return raw[:max_len]
    comp = zlib.compress(raw)
    return comp[:max_len]

def _payload_IHDR(rng: random.Random) -> bytes:
    # 13 bytes: width(4) height(4) bitdepth(1) colortype(1) compression(1)=0 filter(1)=0 interlace(1) in {0,1}
    w = _clamp(int(2 ** rng.randint(0, 12)), 1, 4096)  # 1..4096 typical small sizes
    h = _clamp(int(2 ** rng.randint(0, 12)), 1, 4096)
    bitdepth = rng.choice([1, 2, 4, 8, 16])
    colortype = rng.choice([0, 2, 3, 4, 6])
    # Enforce valid bitdepth/colortype combos per PNG spec
    valid_bits = {
        0: {1, 2, 4, 8, 16},
        2: {8, 16},
        3: {1, 2, 4, 8},
        4: {8, 16},
        6: {8, 16},
    }
    if bitdepth not in valid_bits[colortype]:
        bitdepth = rng.choice(sorted(valid_bits[colortype]))
    compression = 0
    filter_m = 0
    interlace = rng.choice([0, 1])
    return _u32be(w) + _u32be(h) + bytes([bitdepth, colortype, compression, filter_m, interlace])

def _build_chunk(rng: random.Random, ctype: bytes, max_total: int = 4096) -> bytes:
    # Reserve space for header and crc
    overhead = 4 + 4 + 4
    max_payload = max_total - overhead
    max_payload = max(0, max_payload)

    # Choose payload based on type
    if ctype == b"tEXt":
        payload = _payload_tEXt(rng, max_payload)
    elif ctype == b"pHYs":
        payload = _payload_pHYs(rng)
    elif ctype == b"gAMA":
        payload = _payload_gAMA(rng)
    elif ctype == b"iCCP":
        payload = _payload_iCCP(rng, max_payload)
    elif ctype == b"bKGD":
        payload = _payload_bKGD(rng)
    elif ctype == b"tRNS":
        payload = _payload_tRNS(rng)
    elif ctype == b"IDAT":
        payload = _payload_IDAT(rng, max_payload)
    elif ctype == b"IHDR":
        payload = _payload_IHDR(rng)
    else:
        # Generic payload filler
        n = rng.randint(0, min(64, max_payload))
        payload = bytes(rng.getrandbits(8) for _ in range(n))

    # Trim payload if it somehow exceeded
    if len(payload) > max_payload:
        payload = payload[:max_payload]

    length = len(payload)
    # Assemble chunk
    out = bytearray()
    out += _u32be(length)
    out += ctype
    out += payload
    # CRC over type+data
    crc_val = zlib.crc32(ctype + payload) & 0xFFFFFFFF
    out += _u32be(crc_val)
    return bytes(out)


def generate(seed: int) -> bytes:
    rng = random.Random(seed)

    # Prefer chunk types that the stubs exercise and LodePNG knows about
    ctype = rng.choice(ASCII_TYPES)

    # Sometimes bias to types explicitly used in the fuzzer stubs
    if rng.random() < 0.6:
        ctype = rng.choice([b"tEXt", b"pHYs", b"gAMA", b"iCCP", b"bKGD", b"tRNS", b"IDAT"])  # includes IDAT for CRC paths

    chunk = _build_chunk(rng, ctype, max_total=4096)

    # Ensure very small payloads sometimes, matching stub len constraints (e.g., 0..16/32/64)
    if rng.random() < 0.25:
        # Rebuild with a tighter max
        tight_max = rng.choice([4 + 4 + 0 + 4, 4 + 4 + 8 + 4, 4 + 4 + 16 + 4, 4 + 4 + 32 + 4, 4 + 4 + 64 + 4])
        ctype2 = rng.choice([b"tEXt", b"IDAT", ctype])
        chunk = _build_chunk(rng, ctype2, max_total=tight_max)

    return chunk
